H.text("theta_i = " + inc.toFixed(0) + " deg    theta_r = " + inc.toFixed(0) + " deg    (measured from the normal)", 24, 52, { color: H.colors.sub, size: 13 });
// Mirror surface (horizontal) and the point of incidence.
const my = h*0.66, px = w*0.5;
H.line(60, my, w-60, my, { color: H.colors.accent, width: 4 });
for(let x=70;x<w-60;x+=22){ H.line(x, my, x-10, my+10, { color: H.colors.axis, width: 1 }); } // hatching = back of mirror
// Normal (dashed, perpendicular to mirror).
H.line(px, my, px, my-Math.min(h*0.5,260), { color: H.colors.violet, width: 1.5, dash: [6,6] });
H.text("normal", px+8, my-Math.min(h*0.5,260)+14, { color: H.colors.violet, size: 12 });
const L = Math.min(h*0.45, 230);
// Incoming ray comes from upper-left at angle a from normal, hits px,my.
const ix = px - L*Math.sin(a), iy = my - L*Math.cos(a);
H.arrow(ix, iy, px, my, { color: H.colors.warn, width: 3 });
// Reflected ray leaves to upper-right at the SAME angle from normal.
const rx = px + L*Math.sin(a), ry = my - L*Math.cos(a);
H.arrow(px, my, rx, ry, { color: H.colors.good, width: 3 });
