else { const u = (ph-0.5)/0.5; dx = H.lerp(px,rx,u); dy = H.lerp(my,ry,u); }
H.circle(dx, dy, 6, { fill: H.colors.yellow });
// Angle arcs at the surface (from the normal out to each ray).
const arcR = 46;
